
var gameController;
var gameWS=new WebSocket(serverString);

 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"EyeOfRaAM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){
	
		    var tmpMess=k.data.split("#");
	
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.yuy.xjy!=undefined){
			
			if(gameController.rqk!=parseInt(tmpMess[1])){
				
			gameController.rqk=parseInt(tmpMess[1]);	
			gameController.yha=parseInt(tmpMess[1]);	
			gameController.yuy.xjy.htp("creditd", "#laa", [gameController.htd(tmpMess[1]), true]);	
			
			}
			
			
			
			
			
			}	
			
		}
		
